/* READ ONLY Teradata SQL Assistant. Run each numbered SELECT separately.
Full populations, no account sample; no permanent tables/config/run changes.
Uses the analyst-confirmed numeric special list. Counts are account-month events.
Keep the source fixed and reconcile baseline counts to saved results first.
FLOAT casts precede arithmetic. NULL numeric outputs indicate invalid source grain;
absence of rows is not a pass. No individual account results should be uploaded.
*/
/* QUERY 1: field/event overlap, including LOWER/ORIGINAL/HIGHER jumps.
Uses captured numeric run 20 limits and special snapshots (categorical run 19).
NULL counts also indicate missing/inconsistent reference metadata, not a pass.
Do not sum event types: jump scenarios re-evaluate overlapping populations.

QUERY 2: actual linked package keys among accounts with >=2 affected fields.
Uses lower LTI jumps, original jumps for other numeric fields, plus all valid-to-
missing/special transitions. Counts fields once per account; does not count the
same jump three times. STABLE_THRU is a stable longitudinal key; PREVIOUS_PKG only
identifies the prior package, not proof of current membership. Unresolved links
are deliberately excluded, NOT grouped as one NULL package. Query 1 shows how
many lack stable through-time IDs. LINK_KEY values/results must remain internal.
This can establish observed key/account overlap, not common causality, correct
aggregation or that every flagged record is defective. Same NULL does not mean
same package. Flagged fields in one account share that account's package context;
source aggregation keys still require owner confirmation.
*/

/* QUERY 1 */
WITH reference_runs AS
(SELECT DISTINCT RUN_ID,FIELD_TYPE FROM LAB_T_ORION_MVT.DQ_ACCOUNT_REVIEW WHERE PROJECT_ID='RDS' AND ((RUN_NUMBER=19 AND FIELD_TYPE='CATEGORICAL') OR (RUN_NUMBER=20 AND FIELD_TYPE='NUMERIC'))),
ref_control AS (SELECT SUM(CASE WHEN FIELD_TYPE='CATEGORICAL' THEN 1 ELSE 0 END) AS CAT_RUNS,SUM(CASE WHEN FIELD_TYPE='NUMERIC' THEN 1 ELSE 0 END) AS NUM_RUNS FROM reference_runs),
num_meta AS (SELECT DISTINCT FIELD_NAME,CAST(ABS_CHANGE_MIN AS FLOAT) AS A,CAST(REL_CHANGE_MIN AS FLOAT) AS R FROM LAB_T_ORION_MVT.DQ_ACCOUNT_REVIEW WHERE PROJECT_ID='RDS' AND RUN_NUMBER=20 AND FIELD_NAME IN ('PCKG_BOVO_VAL_AMT','PCKG_REPAY_AMT','PCKG_BALANCE_AMT','MV_PCKG_LOAN_TO_INC_RT','MV_PCKG_AVG_PAY_TO_BAL_L6M_RT','MV_PCKG_REPAY_TO_INC_RT','MV_PCKG_SAV_DEP_TO_BALANCE_RT','MV_PCKG_SAV_DEP_TO_REPAY_RT')),
meta_control AS (SELECT COUNT(*) AS N,COUNT(DISTINCT FIELD_NAME) AS F FROM num_meta),
cat_special AS (SELECT DISTINCT UPPER(TRIM(V.SPECIAL_VALUE)) AS CODE FROM LAB_T_ORION_MVT.DQ_RUN_SPECIAL_VALUE V JOIN reference_runs R ON V.RUN_ID=R.RUN_ID AND R.FIELD_TYPE='CATEGORICAL' WHERE V.FIELD_TYPE='CATEGORICAL' AND V.SPECIAL_VALUE IS NOT NULL),
num_special AS (SELECT DISTINCT V.NUMERIC_VALUE AS CODE FROM LAB_T_ORION_MVT.DQ_RUN_SPECIAL_VALUE V JOIN reference_runs R ON V.RUN_ID=R.RUN_ID AND R.FIELD_TYPE='NUMERIC' WHERE V.FIELD_TYPE='NUMERIC' AND V.NUMERIC_VALUE IS NOT NULL),
src AS (SELECT AGMT_ID,CAST(FACT_DT AS DATE) AS POU_DT,EXTRACT(YEAR FROM FACT_DT)*12+EXTRACT(MONTH FROM FACT_DT) AS MK,
 COUNT(*) OVER (PARTITION BY AGMT_ID,EXTRACT(YEAR FROM FACT_DT),EXTRACT(MONTH FROM FACT_DT)) AS KC,
 NULLIF(TRIM(CAST(PCKG_ID AS VARCHAR(128))),'') AS PKG,
 NULLIF(TRIM(CAST(PCKG_THRU_TIME_ID AS VARCHAR(128))),'') AS THRU,
NULLIF(UPPER(TRIM(CAST(EVENT_DESCRIPTION AS VARCHAR(512)))),'') AS EVENT_DESCRIPTION,
NULLIF(UPPER(TRIM(CAST(MV_PROP_POSTCODE_NM AS VARCHAR(512)))),'') AS MV_PROP_POSTCODE_NM,
CAST(PCKG_BOVO_VAL_AMT AS FLOAT) AS PCKG_BOVO_VAL_AMT,
CAST(PCKG_REPAY_AMT AS FLOAT) AS PCKG_REPAY_AMT,
CAST(PCKG_BALANCE_AMT AS FLOAT) AS PCKG_BALANCE_AMT,
CAST(MV_PCKG_LOAN_TO_INC_RT AS FLOAT) AS MV_PCKG_LOAN_TO_INC_RT,
CAST(MV_PCKG_AVG_PAY_TO_BAL_L6M_RT AS FLOAT) AS MV_PCKG_AVG_PAY_TO_BAL_L6M_RT,
CAST(MV_PCKG_REPAY_TO_INC_RT AS FLOAT) AS MV_PCKG_REPAY_TO_INC_RT,
CAST(MV_PCKG_SAV_DEP_TO_BALANCE_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_BALANCE_RT,
CAST(MV_PCKG_SAV_DEP_TO_REPAY_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_REPAY_RT FROM LAB_T_ORION_MVT.VW_RDS_PHASE2_FACT WHERE CAST(FACT_DT AS DATE) IN (DATE '2019-01-31',DATE '2019-02-28',DATE '2019-04-30',DATE '2019-05-31',DATE '2020-01-31',DATE '2020-02-29',DATE '2022-02-28',DATE '2022-03-31',DATE '2024-10-31',DATE '2024-11-30')),
key_control AS (SELECT SUM(CASE WHEN AGMT_ID IS NULL OR KC<>1 THEN 1 ELSE 0 END) AS BAD FROM src),
 vals AS (
SELECT CAST('EVENT_DESCRIPTION' AS VARCHAR(64)) AS FIELD_NAME,CAST('CATEGORICAL' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,CAST(NULL AS FLOAT) AS V,EVENT_DESCRIPTION AS CV FROM src UNION ALL
SELECT CAST('MV_PROP_POSTCODE_NM' AS VARCHAR(64)) AS FIELD_NAME,CAST('CATEGORICAL' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,CAST(NULL AS FLOAT) AS V,MV_PROP_POSTCODE_NM AS CV FROM src UNION ALL
SELECT CAST('PCKG_BOVO_VAL_AMT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,PCKG_BOVO_VAL_AMT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('PCKG_REPAY_AMT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,PCKG_REPAY_AMT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('PCKG_BALANCE_AMT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,PCKG_BALANCE_AMT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_LOAN_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_LOAN_TO_INC_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_AVG_PAY_TO_BAL_L6M_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_AVG_PAY_TO_BAL_L6M_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_REPAY_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_REPAY_TO_INC_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_SAV_DEP_TO_BALANCE_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_SAV_DEP_TO_BALANCE_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_SAV_DEP_TO_REPAY_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_SAV_DEP_TO_REPAY_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src), st AS (SELECT V.*,CASE WHEN (TP='NUMERIC' AND V.V IS NULL) OR (TP='CATEGORICAL' AND CV IS NULL) THEN 'MISSING' WHEN NS.CODE IS NOT NULL OR CS.CODE IS NOT NULL THEN 'SPECIAL' ELSE 'VALID' END AS VS
 FROM vals V LEFT JOIN num_special NS ON V.TP='NUMERIC' AND V.V=NS.CODE LEFT JOIN cat_special CS ON V.TP='CATEGORICAL' AND CV=CS.CODE),
 h AS (SELECT S.*,LAG(V) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PV,LAG(VS) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PS,LAG(MK) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PM,LAG(PKG) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PPKG,LAG(THRU) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PTHRU FROM st S),
 seed AS (SELECT COUNT(*) AS N FROM src),
 scenarios AS (SELECT CAST('TO_MISSING' AS VARCHAR(16)) AS EVENT_TYPE,CAST(NULL AS FLOAT) AS AF,CAST(NULL AS FLOAT) AS RF FROM seed
 UNION ALL SELECT CAST('TO_SPECIAL' AS VARCHAR(16)),CAST(NULL AS FLOAT),CAST(NULL AS FLOAT) FROM seed
 UNION ALL SELECT CAST('JUMP_LOWER' AS VARCHAR(16)),CAST(0.5 AS FLOAT),CAST(0.5 AS FLOAT) FROM seed
 UNION ALL SELECT CAST('JUMP_ORIGINAL' AS VARCHAR(16)),CAST(1 AS FLOAT),CAST(1 AS FLOAT) FROM seed
 UNION ALL SELECT CAST('JUMP_HIGHER' AS VARCHAR(16)),CAST(2 AS FLOAT),CAST(1.5 AS FLOAT) FROM seed),
 f AS (SELECT H.*,C.EVENT_TYPE,
 CASE WHEN PS='VALID' AND MK-PM=1 AND
 ((C.EVENT_TYPE='TO_MISSING' AND VS='MISSING') OR (C.EVENT_TYPE='TO_SPECIAL' AND VS='SPECIAL') OR
 (C.AF IS NOT NULL AND TP='NUMERIC' AND VS='VALID' AND ABS(V-PV)>=M.A*C.AF AND (PV=0 OR ABS((V-PV)/NULLIFZERO(ABS(PV)))>=M.R*C.RF))) THEN 1 ELSE 0 END AS FLAG
 FROM h H CROSS JOIN scenarios C LEFT JOIN num_meta M ON H.FIELD_NAME=M.FIELD_NAME
 WHERE POU_DT IN (DATE '2019-02-28',DATE '2019-05-31',DATE '2020-02-29',DATE '2022-03-31',DATE '2024-11-30')),
 ctl AS (SELECT CASE WHEN COALESCE(K.BAD,0)=0 AND R.CAT_RUNS=1 AND R.NUM_RUNS=1 AND M.N=8 AND M.F=8 THEN 1 ELSE 0 END AS OK FROM key_control K CROSS JOIN ref_control R CROSS JOIN meta_control M)
SELECT FIELD_NAME,POU_DT,EVENT_TYPE,
 CASE WHEN MAX(OK)=1 THEN SUM(FLAG) END AS EVENT_COUNT,
 CASE WHEN MAX(OK)=1 THEN SUM(CASE WHEN FLAG=1 AND PKG IS NULL THEN 1 ELSE 0 END) END AS CURRENT_PKG_MISSING,
 CASE WHEN MAX(OK)=1 THEN SUM(CASE WHEN FLAG=1 AND PKG IS NULL AND PPKG IS NOT NULL THEN 1 ELSE 0 END) END AS PKG_BECAME_MISSING,
 CASE WHEN MAX(OK)=1 THEN SUM(CASE WHEN FLAG=1 AND THRU IS NOT NULL AND PTHRU=THRU THEN 1 ELSE 0 END) END AS STABLE_THRU_COUNT,
 CASE WHEN MAX(OK)=1 THEN SUM(CASE WHEN FLAG=1 AND THRU<>PTHRU THEN 1 ELSE 0 END) END AS POPULATED_THRU_CHANGED
FROM f CROSS JOIN ctl GROUP BY FIELD_NAME,POU_DT,EVENT_TYPE
HAVING SUM(FLAG)>0 ORDER BY FIELD_NAME,POU_DT,EVENT_TYPE;

/* QUERY 2: run separately */
WITH reference_runs AS
(SELECT DISTINCT RUN_ID,FIELD_TYPE FROM LAB_T_ORION_MVT.DQ_ACCOUNT_REVIEW WHERE PROJECT_ID='RDS' AND ((RUN_NUMBER=19 AND FIELD_TYPE='CATEGORICAL') OR (RUN_NUMBER=20 AND FIELD_TYPE='NUMERIC'))),
ref_control AS (SELECT SUM(CASE WHEN FIELD_TYPE='CATEGORICAL' THEN 1 ELSE 0 END) AS CAT_RUNS,SUM(CASE WHEN FIELD_TYPE='NUMERIC' THEN 1 ELSE 0 END) AS NUM_RUNS FROM reference_runs),
num_meta AS (SELECT DISTINCT FIELD_NAME,CAST(ABS_CHANGE_MIN AS FLOAT) AS A,CAST(REL_CHANGE_MIN AS FLOAT) AS R FROM LAB_T_ORION_MVT.DQ_ACCOUNT_REVIEW WHERE PROJECT_ID='RDS' AND RUN_NUMBER=20 AND FIELD_NAME IN ('PCKG_BOVO_VAL_AMT','PCKG_REPAY_AMT','PCKG_BALANCE_AMT','MV_PCKG_LOAN_TO_INC_RT','MV_PCKG_AVG_PAY_TO_BAL_L6M_RT','MV_PCKG_REPAY_TO_INC_RT','MV_PCKG_SAV_DEP_TO_BALANCE_RT','MV_PCKG_SAV_DEP_TO_REPAY_RT')),
meta_control AS (SELECT COUNT(*) AS N,COUNT(DISTINCT FIELD_NAME) AS F FROM num_meta),
cat_special AS (SELECT DISTINCT UPPER(TRIM(V.SPECIAL_VALUE)) AS CODE FROM LAB_T_ORION_MVT.DQ_RUN_SPECIAL_VALUE V JOIN reference_runs R ON V.RUN_ID=R.RUN_ID AND R.FIELD_TYPE='CATEGORICAL' WHERE V.FIELD_TYPE='CATEGORICAL' AND V.SPECIAL_VALUE IS NOT NULL),
num_special AS (SELECT DISTINCT V.NUMERIC_VALUE AS CODE FROM LAB_T_ORION_MVT.DQ_RUN_SPECIAL_VALUE V JOIN reference_runs R ON V.RUN_ID=R.RUN_ID AND R.FIELD_TYPE='NUMERIC' WHERE V.FIELD_TYPE='NUMERIC' AND V.NUMERIC_VALUE IS NOT NULL),
src AS (SELECT AGMT_ID,CAST(FACT_DT AS DATE) AS POU_DT,EXTRACT(YEAR FROM FACT_DT)*12+EXTRACT(MONTH FROM FACT_DT) AS MK,
 COUNT(*) OVER (PARTITION BY AGMT_ID,EXTRACT(YEAR FROM FACT_DT),EXTRACT(MONTH FROM FACT_DT)) AS KC,
 NULLIF(TRIM(CAST(PCKG_ID AS VARCHAR(128))),'') AS PKG,
 NULLIF(TRIM(CAST(PCKG_THRU_TIME_ID AS VARCHAR(128))),'') AS THRU,
NULLIF(UPPER(TRIM(CAST(EVENT_DESCRIPTION AS VARCHAR(512)))),'') AS EVENT_DESCRIPTION,
NULLIF(UPPER(TRIM(CAST(MV_PROP_POSTCODE_NM AS VARCHAR(512)))),'') AS MV_PROP_POSTCODE_NM,
CAST(PCKG_BOVO_VAL_AMT AS FLOAT) AS PCKG_BOVO_VAL_AMT,
CAST(PCKG_REPAY_AMT AS FLOAT) AS PCKG_REPAY_AMT,
CAST(PCKG_BALANCE_AMT AS FLOAT) AS PCKG_BALANCE_AMT,
CAST(MV_PCKG_LOAN_TO_INC_RT AS FLOAT) AS MV_PCKG_LOAN_TO_INC_RT,
CAST(MV_PCKG_AVG_PAY_TO_BAL_L6M_RT AS FLOAT) AS MV_PCKG_AVG_PAY_TO_BAL_L6M_RT,
CAST(MV_PCKG_REPAY_TO_INC_RT AS FLOAT) AS MV_PCKG_REPAY_TO_INC_RT,
CAST(MV_PCKG_SAV_DEP_TO_BALANCE_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_BALANCE_RT,
CAST(MV_PCKG_SAV_DEP_TO_REPAY_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_REPAY_RT FROM LAB_T_ORION_MVT.VW_RDS_PHASE2_FACT WHERE CAST(FACT_DT AS DATE) IN (DATE '2019-01-31',DATE '2019-02-28',DATE '2019-04-30',DATE '2019-05-31',DATE '2020-01-31',DATE '2020-02-29',DATE '2022-02-28',DATE '2022-03-31',DATE '2024-10-31',DATE '2024-11-30')),
key_control AS (SELECT SUM(CASE WHEN AGMT_ID IS NULL OR KC<>1 THEN 1 ELSE 0 END) AS BAD FROM src),
 vals AS (
SELECT CAST('EVENT_DESCRIPTION' AS VARCHAR(64)) AS FIELD_NAME,CAST('CATEGORICAL' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,CAST(NULL AS FLOAT) AS V,EVENT_DESCRIPTION AS CV FROM src UNION ALL
SELECT CAST('MV_PROP_POSTCODE_NM' AS VARCHAR(64)) AS FIELD_NAME,CAST('CATEGORICAL' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,CAST(NULL AS FLOAT) AS V,MV_PROP_POSTCODE_NM AS CV FROM src UNION ALL
SELECT CAST('PCKG_BOVO_VAL_AMT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,PCKG_BOVO_VAL_AMT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('PCKG_REPAY_AMT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,PCKG_REPAY_AMT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('PCKG_BALANCE_AMT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,PCKG_BALANCE_AMT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_LOAN_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_LOAN_TO_INC_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_AVG_PAY_TO_BAL_L6M_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_AVG_PAY_TO_BAL_L6M_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_REPAY_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_REPAY_TO_INC_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_SAV_DEP_TO_BALANCE_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_SAV_DEP_TO_BALANCE_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src UNION ALL
SELECT CAST('MV_PCKG_SAV_DEP_TO_REPAY_RT' AS VARCHAR(64)) AS FIELD_NAME,CAST('NUMERIC' AS VARCHAR(16)) AS TP,AGMT_ID,POU_DT,MK,PKG,THRU,MV_PCKG_SAV_DEP_TO_REPAY_RT AS V,CAST(NULL AS VARCHAR(512)) AS CV FROM src), st AS (SELECT V.*,CASE WHEN (TP='NUMERIC' AND V.V IS NULL) OR (TP='CATEGORICAL' AND CV IS NULL) THEN 'MISSING' WHEN NS.CODE IS NOT NULL OR CS.CODE IS NOT NULL THEN 'SPECIAL' ELSE 'VALID' END AS VS
 FROM vals V LEFT JOIN num_special NS ON V.TP='NUMERIC' AND V.V=NS.CODE LEFT JOIN cat_special CS ON V.TP='CATEGORICAL' AND CV=CS.CODE),
 h AS (SELECT S.*,LAG(V) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PV,LAG(VS) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PS,LAG(MK) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PM,LAG(PKG) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PPKG,LAG(THRU) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PTHRU FROM st S),
 seed AS (SELECT COUNT(*) AS N FROM src),
 scenarios AS (SELECT CAST('TO_MISSING' AS VARCHAR(16)) AS EVENT_TYPE,CAST(NULL AS FLOAT) AS AF,CAST(NULL AS FLOAT) AS RF FROM seed
 UNION ALL SELECT CAST('TO_SPECIAL' AS VARCHAR(16)),CAST(NULL AS FLOAT),CAST(NULL AS FLOAT) FROM seed
 UNION ALL SELECT CAST('JUMP_LOWER' AS VARCHAR(16)),CAST(0.5 AS FLOAT),CAST(0.5 AS FLOAT) FROM seed
 UNION ALL SELECT CAST('JUMP_ORIGINAL' AS VARCHAR(16)),CAST(1 AS FLOAT),CAST(1 AS FLOAT) FROM seed
 UNION ALL SELECT CAST('JUMP_HIGHER' AS VARCHAR(16)),CAST(2 AS FLOAT),CAST(1.5 AS FLOAT) FROM seed),
 f AS (SELECT H.*,C.EVENT_TYPE,
 CASE WHEN PS='VALID' AND MK-PM=1 AND
 ((C.EVENT_TYPE='TO_MISSING' AND VS='MISSING') OR (C.EVENT_TYPE='TO_SPECIAL' AND VS='SPECIAL') OR
 (C.AF IS NOT NULL AND TP='NUMERIC' AND VS='VALID' AND ABS(V-PV)>=M.A*C.AF AND (PV=0 OR ABS((V-PV)/NULLIFZERO(ABS(PV)))>=M.R*C.RF))) THEN 1 ELSE 0 END AS FLAG
 FROM h H CROSS JOIN scenarios C LEFT JOIN num_meta M ON H.FIELD_NAME=M.FIELD_NAME
 WHERE POU_DT IN (DATE '2019-02-28',DATE '2019-05-31',DATE '2020-02-29',DATE '2022-03-31',DATE '2024-11-30')),
 ctl AS (SELECT CASE WHEN COALESCE(K.BAD,0)=0 AND R.CAT_RUNS=1 AND R.NUM_RUNS=1 AND M.N=8 AND M.F=8 THEN 1 ELSE 0 END AS OK FROM key_control K CROSS JOIN ref_control R CROSS JOIN meta_control M)
, selected AS (SELECT F.* FROM f F WHERE FLAG=1 AND
 (EVENT_TYPE IN ('TO_MISSING','TO_SPECIAL') OR
 (FIELD_NAME='MV_PCKG_LOAN_TO_INC_RT' AND EVENT_TYPE='JUMP_LOWER') OR
 (FIELD_NAME<>'MV_PCKG_LOAN_TO_INC_RT' AND EVENT_TYPE='JUMP_ORIGINAL'))),
 account_overlap AS (SELECT AGMT_ID,POU_DT,PKG,THRU,PPKG,PTHRU,COUNT(DISTINCT FIELD_NAME) AS FIELD_COUNT FROM selected GROUP BY AGMT_ID,POU_DT,PKG,THRU,PPKG,PTHRU),
 linked AS (SELECT A.*,CASE WHEN THRU IS NOT NULL AND THRU=PTHRU THEN 'STABLE_THRU' WHEN PPKG IS NOT NULL THEN 'PREVIOUS_PKG' ELSE 'UNRESOLVED' END AS LINK_TYPE,
 CASE WHEN THRU IS NOT NULL AND THRU=PTHRU THEN THRU WHEN PPKG IS NOT NULL THEN PPKG END AS LINK_KEY
 FROM account_overlap A WHERE FIELD_COUNT>=2)
SELECT POU_DT,LINK_TYPE,LINK_KEY,
 CASE WHEN MAX(OK)=1 THEN COUNT(*) END AS ACCOUNT_COUNT,
 CASE WHEN MAX(OK)=1 THEN MIN(FIELD_COUNT) END AS MIN_FIELDS_FLAGGED,
 CASE WHEN MAX(OK)=1 THEN MAX(FIELD_COUNT) END AS MAX_FIELDS_FLAGGED,
 CASE WHEN MAX(OK)=1 THEN SUM(CASE WHEN PKG IS NULL THEN 1 ELSE 0 END) END AS CURRENT_PKG_MISSING,
 CASE WHEN MAX(OK)=1 THEN COUNT(DISTINCT PPKG) END AS DISTINCT_PREVIOUS_PKG_IDS
FROM linked CROSS JOIN ctl WHERE LINK_TYPE<>'UNRESOLVED'
GROUP BY POU_DT,LINK_TYPE,LINK_KEY ORDER BY POU_DT,LINK_TYPE,LINK_KEY;
